package com.ruoyi.web.biz;
import java.util.*;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.math.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.AccessDeniedException;
import com.ruoyi.common.utils.SecurityUtils;
import com.ruoyi.common.exception.ServiceException;
@Service
public class StatisticsService {
 final JdbcTemplate db;final EmployeeService users;final TaskService tasks;final DailyReportService reports;
 public StatisticsService(CompanyOnboardingMapper mapper,EmployeeService users,TaskService tasks,DailyReportService reports){db=mapper.database();this.users=users;this.tasks=tasks;this.reports=reports;}
 static final Map<String,String> TITLES=new LinkedHashMap<>();static{TITLES.put("overview","统计工作台");TITLES.put("outputs","企业业务产值");TITLES.put("projects","项目执行与进度");TITLES.put("estimates","项目预估产值");TITLES.put("personnel","人员与就业");TITLES.put("reconciliation","月度核对与差异");TITLES.put("full","平台全量业务报表");}
 boolean platform(){return SecurityUtils.getUserId()==1||users.hasRole(SecurityUtils.getUserId(),"platform_admin");}
 void perm(String p){if(!users.hasPermission("biz:statistics:"+p))throw new AccessDeniedException("无统计报表权限");}
 Set<String> allowed(){perm("read");if(platform())return TITLES.keySet();Set<String> kinds=new LinkedHashSet<>();long user=SecurityUtils.getUserId();if(users.hasRole(user,"company_admin"))kinds.addAll(List.of("overview","outputs","projects","estimates","personnel","reconciliation"));if(users.hasRole(user,"company_business"))kinds.addAll(List.of("overview","outputs","projects","estimates"));if(users.hasRole(user,"company_finance"))kinds.addAll(List.of("overview","outputs","projects","estimates","reconciliation"));if(users.hasRole(user,"company_hr"))kinds.add("personnel");return kinds;}
 Long tenant(Long requested){if(platform()){if(requested!=null&&db.queryForObject("SELECT COUNT(*) FROM biz_company WHERE id=?",Long.class,requested)!=1)throw new ServiceException("企业不存在",404);return requested;}Long c=users.userCompany(SecurityUtils.getUserId());if(c==null||requested!=null&&!requested.equals(c))throw new AccessDeniedException("企业归属无效或越权");return c;}
 public Map<String,Object> options(){Set<String> kinds=allowed();Long c=tenant(null);if(kinds.isEmpty())throw new AccessDeniedException("当前角色无授权报表");List<Map<String,Object>> opts=new ArrayList<>();for(String k:TITLES.keySet())if(kinds.contains(k))opts.add(Map.of("key",k,"label",TITLES.get(k)));return Map.of("kinds",opts,"companies",db.queryForList("SELECT id,company_name FROM biz_company"+(c==null?"":" WHERE id=?")+" ORDER BY id",c==null?new Object[]{}:new Object[]{c}),"allCompanies",platform(),"canPrice",users.hasPermission("biz:statistics:price"),"canExport",users.hasPermission("biz:statistics:export"));}
 public record Filter(Long company,LocalDate from,LocalDate to,String group){}
 Filter filter(Long requested,LocalDate from,LocalDate to,String group){Long c=tenant(requested);LocalDate today=LocalDate.now(ZoneId.of("Asia/Shanghai"));if(from==null)from=today.withDayOfMonth(1);if(to==null)to=today;if(from.isAfter(to)||to.isAfter(today)||ChronoUnit.DAYS.between(from,to)>365||!Set.of("DAY","MONTH").contains(group))throw new ServiceException("日期范围须为过去366天以内的区间，分组须为DAY/MONTH",400);return new Filter(c,from,to,group);}
 String scope(String alias){return "(? IS NULL OR "+alias+"company_id=?)";}
 List<Map<String,Object>> bounded(String sql,Object...args){var rows=db.queryForList(sql+" LIMIT 10001",args);if(rows.size()>10000)throw new ServiceException("结果超过10000条，请选择企业或缩小日期范围",413);return rows;}
 BigDecimal decimal(Object x){return x==null?BigDecimal.ZERO:(BigDecimal)x;}
 BigDecimal total(List<Map<String,Object>> rows,String key){BigDecimal sum=BigDecimal.ZERO;for(var row:rows)sum=sum.add(decimal(row.get(key)));return sum;}
 String key(Object company,Object date){return company+"/"+date;}
 List<Map<String,Object>> outputs(Filter f){var rows=bounded("SELECT d.id,d.company_id,c.company_name,d.output_date,d.output_value,d.unit,d.status,d.remark FROM biz_daily_output d JOIN biz_company c ON c.id=d.company_id WHERE "+scope("d.")+" AND d.output_date BETWEEN ? AND ? ORDER BY d.output_date,d.company_id",f.company,f.company,f.from,f.to);for(var row:rows)if(Set.of("SUBMITTED","CONFIRMED").contains(row.get("status"))&&!"元".equals(row.get("unit")))throw new ServiceException("所选范围含非元的已提交数据，请先核对单位",409);return rows;}
 List<Map<String,Object>> trend(Filter f,List<Map<String,Object>> rows){Map<String,Map<String,Object>> groups=new LinkedHashMap<>();for(LocalDate d=f.from;!d.isAfter(f.to);d=d.plusDays(1)){String k=f.group.equals("MONTH")?YearMonth.from(d).toString():d.toString();groups.putIfAbsent(k,new LinkedHashMap<>(Map.of("period",k,"reported",BigDecimal.ZERO,"confirmed",BigDecimal.ZERO)));}for(var row:rows){LocalDate d=((java.sql.Date)row.get("output_date")).toLocalDate();String k=f.group.equals("MONTH")?YearMonth.from(d).toString():d.toString();if(Set.of("SUBMITTED","CONFIRMED").contains(row.get("status"))){var g=groups.get(k);g.put("reported",decimal(g.get("reported")).add(decimal(row.get("output_value"))));if("CONFIRMED".equals(row.get("status")))g.put("confirmed",decimal(g.get("confirmed")).add(decimal(row.get("output_value"))));}}return new ArrayList<>(groups.values());}
 long missing(Filter f,List<Map<String,Object>> rows){var rule=reports.rule();var calendar=reports.calendar();LocalDate last=f.to.isBefore(reports.due(rule))?f.to:reports.due(rule);Set<String> done=new HashSet<>();for(var row:rows)if(Set.of("SUBMITTED","CONFIRMED").contains(row.get("status")))done.add(key(row.get("company_id"),row.get("output_date")));long count=0;for(var company:bounded("SELECT id,COALESCE(reporting_start_date,DATE(create_time)) AS first_day FROM biz_company WHERE status='ACTIVE' AND (? IS NULL OR id=?)",f.company,f.company)){LocalDate first=((java.sql.Date)company.get("first_day")).toLocalDate();if(first.isBefore(f.from))first=f.from;for(LocalDate d=first;!d.isAfter(last);d=d.plusDays(1))if(reports.required(d,rule,calendar)&&!done.contains(key(company.get("id"),d)))count++;}return count;}
 Map<String,Object> outputSummary(Filter f,List<Map<String,Object>> rows){BigDecimal submitted=BigDecimal.ZERO,confirmed=BigDecimal.ZERO,draft=BigDecimal.ZERO,returned=BigDecimal.ZERO;for(var row:rows){BigDecimal v=decimal(row.get("output_value"));switch(String.valueOf(row.get("status"))){case "SUBMITTED":submitted=submitted.add(v);break;case "CONFIRMED":confirmed=confirmed.add(v);break;case "DRAFT":draft=draft.add(v);break;case "RETURNED":returned=returned.add(v);break;default:break;}}return Map.of("reportedValue",submitted.add(confirmed),"confirmedValue",confirmed,"submittedValue",submitted,"draftValue",draft,"returnedValue",returned,"recordCount",rows.size(),"missingDays",missing(f,rows));}
 Map<String,Object> overview(Filter f){LocalDate today=LocalDate.now(ZoneId.of("Asia/Shanghai"));Filter current=new Filter(f.company,today.withDayOfMonth(1),today,"DAY");var rows=outputs(f);var currentRows=outputs(current);var summary=new LinkedHashMap<String,Object>();summary.put("companyCount",db.queryForObject("SELECT COUNT(*) FROM biz_company WHERE (? IS NULL OR id=?)",Long.class,f.company,f.company));summary.put("activeCompanyCount",db.queryForObject("SELECT COUNT(*) FROM biz_company WHERE status='ACTIVE' AND (? IS NULL OR id=?)",Long.class,f.company,f.company));summary.put("employeeCount",db.queryForObject("SELECT COUNT(DISTINCT user_id) FROM biz_employee_info WHERE "+scope(""),Long.class,f.company,f.company));summary.put("activeEmployeeCount",db.queryForObject("SELECT COUNT(DISTINCT user_id) FROM biz_employee_info WHERE status='ACTIVE' AND "+scope(""),Long.class,f.company,f.company));summary.put("projectCount",db.queryForObject("SELECT COUNT(*) FROM biz_project WHERE "+scope(""),Long.class,f.company,f.company));summary.put("monthReportedValue",currentRows.stream().filter(x->Set.of("SUBMITTED","CONFIRMED").contains(x.get("status"))).map(x->decimal(x.get("output_value"))).reduce(BigDecimal.ZERO,BigDecimal::add));summary.putAll(outputSummary(f,rows));return Map.of("summary",summary,"rows",trend(f,rows),"trend",trend(f,rows));}
 List<Map<String,Object>> personnel(Filter f){return bounded("SELECT e.id,e.company_id,c.company_name,e.user_id,e.employee_no,e.real_name,e.contact_phone,e.job_title,e.status,e.entry_date,e.leave_date FROM biz_employee_info e JOIN biz_company c ON c.id=e.company_id WHERE "+scope("e.")+" ORDER BY e.company_id,e.id",f.company,f.company);}
 Map<String,Object> peopleSummary(Filter f,List<Map<String,Object>> rows){long active=0,left=0,entry=0,depart=0;Set<Object> distinct=new HashSet<>();for(var row:rows){distinct.add(row.get("user_id"));if("ACTIVE".equals(row.get("status")))active++;if("LEFT".equals(row.get("status")))left++;if(row.get("entry_date")!=null){LocalDate d=((java.sql.Date)row.get("entry_date")).toLocalDate();if(!d.isBefore(f.from)&&!d.isAfter(f.to))entry++;}if(row.get("leave_date")!=null){LocalDate d=((java.sql.Date)row.get("leave_date")).toLocalDate();if(!d.isBefore(f.from)&&!d.isAfter(f.to))depart++;}}return Map.of("profileCount",rows.size(),"distinctUserCount",distinct.size(),"activeProfiles",active,"leftProfiles",left,"currentEntryInPeriod",entry,"currentLeaveInPeriod",depart);}
 List<Map<String,Object>> projectRows(Filter f){var projects=bounded("SELECT p.id,p.company_id,c.company_name,p.project_code,p.project_name,p.unit,p.status FROM biz_project p JOIN biz_company c ON c.id=p.company_id WHERE "+scope("p.")+" ORDER BY p.company_id,p.id",f.company,f.company);var links=bounded("SELECT l.*,t.title FROM biz_project_task l JOIN biz_task t ON t.id=l.task_id WHERE "+scope("l."),f.company,f.company);var work=bounded("SELECT a.project_id,a.task_id,SUM(w.quantity) AS confirmed_qty,SUM(CASE WHEN w.work_date BETWEEN ? AND ? THEN w.quantity ELSE 0 END) AS period_qty FROM biz_work_record w JOIN biz_task_assignment a ON a.id=w.assignment_id AND a.company_id=w.company_id WHERE a.project_id IS NOT NULL AND w.status='CONFIRMED' AND "+scope("a.")+" GROUP BY a.project_id,a.task_id",f.from,f.to,f.company,f.company);Map<String,Map<String,Object>> done=new HashMap<>();for(var w:work)done.put(key(w.get("project_id"),w.get("task_id")),w);
 for(var p:projects){BigDecimal target=BigDecimal.ZERO,confirmed=BigDecimal.ZERO,period=BigDecimal.ZERO,planned=BigDecimal.ZERO,actual=BigDecimal.ZERO,periodValue=BigDecimal.ZERO;int priced=0,unpriced=0;List<Map<String,Object>> details=new ArrayList<>();for(var l:links)if(l.get("project_id").equals(p.get("id"))){BigDecimal q=decimal(l.get("target_quantity"));var w=done.get(key(l.get("project_id"),l.get("task_id")));BigDecimal dq=w==null?BigDecimal.ZERO:decimal(w.get("confirmed_qty")),pq=w==null?BigDecimal.ZERO:decimal(w.get("period_qty"));target=target.add(q);confirmed=confirmed.add(dq);period=period.add(pq);Map<String,Object> line=new LinkedHashMap<>();line.put("projectId",p.get("id"));line.put("projectName",p.get("project_name"));line.put("taskId",l.get("task_id"));line.put("taskTitle",l.get("title"));line.put("unit",l.get("unit"));line.put("plannedQuantity",q);line.put("confirmedQuantity",dq);line.put("unitPrice",l.get("unit_price"));line.put("priceVersion",l.get("price_version"));line.put("priceSnapshotTime",l.get("price_snapshot_time"));if(l.get("unit_price")==null){unpriced++;line.put("plannedEstimate",null);line.put("confirmedEstimate",null);}else{priced++;BigDecimal price=decimal(l.get("unit_price")),pe=q.multiply(price).setScale(2,RoundingMode.HALF_UP),ce=dq.multiply(price).setScale(2,RoundingMode.HALF_UP);planned=planned.add(pe);actual=actual.add(ce);periodValue=periodValue.add(pq.multiply(price).setScale(2,RoundingMode.HALF_UP));line.put("plannedEstimate",pe);line.put("confirmedEstimate",ce);}details.add(line);}
 p.put("totalQuantity",target);p.put("confirmedQuantity",confirmed);p.put("periodConfirmedQuantity",period);p.put("remainingQuantity",target.subtract(confirmed));p.put("percent",target.signum()==0?BigDecimal.ZERO:confirmed.multiply(new BigDecimal("100")).divide(target,2,RoundingMode.HALF_UP));p.put("pricedTaskCount",priced);p.put("unpricedTaskCount",unpriced);p.put("plannedEstimate",unpriced>0||details.isEmpty()?null:planned);p.put("confirmedEstimate",unpriced>0||details.isEmpty()?null:actual);p.put("periodConfirmedEstimate",unpriced>0||details.isEmpty()?null:periodValue);p.put("pricedPlannedSubtotal",planned);p.put("quoteLines",details);}
 return projects;}
 List<Map<String,Object>> reconciliation(Filter f){LocalDate from=f.from.withDayOfMonth(1),to=YearMonth.from(f.to).atEndOfMonth();var full=new Filter(f.company,from,to,"MONTH");var rows=outputs(full);Map<String,BigDecimal> totals=new HashMap<>(),confirmed=new HashMap<>();Map<String,Integer> counts=new HashMap<>();for(var row:rows)if(Set.of("SUBMITTED","CONFIRMED").contains(row.get("status"))){String k=key(row.get("company_id"),String.valueOf(row.get("output_date")).substring(0,7));totals.merge(k,decimal(row.get("output_value")),BigDecimal::add);counts.merge(k,1,Integer::sum);if("CONFIRMED".equals(row.get("status")))confirmed.merge(k,decimal(row.get("output_value")),BigDecimal::add);}
 var audits=bounded("SELECT * FROM biz_report_month_audit WHERE "+scope("")+" AND report_month BETWEEN ? AND ? ORDER BY id DESC",f.company,f.company,YearMonth.from(from).toString(),YearMonth.from(to).toString());Map<String,Map<String,Object>> snapshots=new HashMap<>();for(var a:audits)snapshots.putIfAbsent(key(a.get("company_id"),a.get("report_month")),a);var states=bounded("SELECT * FROM biz_report_month WHERE "+scope("")+" AND report_month BETWEEN ? AND ?",f.company,f.company,YearMonth.from(from).toString(),YearMonth.from(to).toString());Map<String,String> status=new HashMap<>();for(var a:states)status.put(key(a.get("company_id"),a.get("report_month")),String.valueOf(a.get("status")));List<Map<String,Object>> result=new ArrayList<>();for(var c:bounded("SELECT id,company_name FROM biz_company WHERE (? IS NULL OR id=?) ORDER BY id",f.company,f.company))for(YearMonth m=YearMonth.from(from);!m.isAfter(YearMonth.from(to));m=m.plusMonths(1)){String k=key(c.get("id"),m);var audit=snapshots.get(k);BigDecimal value=totals.getOrDefault(k,BigDecimal.ZERO);Map<String,Object> row=new LinkedHashMap<>();row.put("company_id",c.get("id"));row.put("company_name",c.get("company_name"));row.put("reportMonth",m.toString());row.put("reportedValue",value);row.put("confirmedValue",confirmed.getOrDefault(k,BigDecimal.ZERO));row.put("recordCount",counts.getOrDefault(k,0));row.put("snapshotValue",audit==null?null:audit.get("total_value"));row.put("difference",audit==null?null:value.subtract(decimal(audit.get("total_value"))));row.put("snapshotAction",audit==null?null:audit.get("action"));row.put("snapshotTime",audit==null?null:audit.get("create_time"));row.put("checkStatus",status.getOrDefault(k,"UNREVIEWED"));result.add(row);if(result.size()>10000)throw new ServiceException("核对范围超过10000行，请选择企业或缩小日期",413);}return result;}
 public Map<String,Object> report(String kind,Long requested,LocalDate from,LocalDate to,String group,int page,int size){if(!TITLES.containsKey(kind))throw new ServiceException("报表类型无效",400);if(!allowed().contains(kind))throw new AccessDeniedException("当前角色无该报表权限");if(page<1||size<1||size>100||page>100000)throw new ServiceException("分页无效",400);Filter f=filter(requested,from,to,group);Map<String,Object> data=dataset(kind,f);var rows=(List<Map<String,Object>>)data.get("rows");int begin=Math.min(rows.size(),(page-1)*size),end=Math.min(rows.size(),begin+size);Map<String,Object> out=new LinkedHashMap<>(data);out.put("rows",new ArrayList<>(rows.subList(begin,end)));out.put("total",rows.size());out.put("kind",kind);out.put("from",f.from);out.put("to",f.to);out.put("companyId",f.company);return out;}
 Map<String,Object> dataset(String kind,Filter f){if(kind.equals("overview"))return overview(f);if(kind.equals("outputs")){var rows=outputs(f);return Map.of("rows",rows,"summary",outputSummary(f,rows),"trend",trend(f,rows));}if(kind.equals("personnel")){var rows=personnel(f);return Map.of("rows",rows,"summary",peopleSummary(f,rows));}if(kind.equals("projects")||kind.equals("estimates")){var rows=projectRows(f);return Map.of("rows",rows,"summary",Map.of("projectCount",rows.size(),"completedProjects",rows.stream().filter(p->Set.of("COMPLETED","ARCHIVED").contains(p.get("status"))).count(),"unpricedProjects",rows.stream().filter(p->p.get("plannedEstimate")==null).count()));}if(kind.equals("reconciliation")){var rows=reconciliation(f);return Map.of("rows",rows,"summary",Map.of("rows",rows.size(),"confirmedMonths",rows.stream().filter(x->"CONFIRMED".equals(x.get("checkStatus"))).count(),"snapshotMissing",rows.stream().filter(x->x.get("snapshotValue")==null).count()));}
 var tables=new LinkedHashMap<String,List<Map<String,Object>>>();tables.put("企业",bounded("SELECT id,company_name,credit_code,status,create_time FROM biz_company WHERE (? IS NULL OR id=?) ORDER BY id",f.company,f.company));tables.put("人员档案",personnel(f));tables.put("项目执行",projectRows(f));tables.put("每日业务产值",outputs(f));tables.put("月度核对",reconciliation(f));tables.put("工作量明细",bounded("SELECT w.id,w.company_id,w.user_id,a.project_id,w.assignment_id,w.work_date,w.quantity,w.status,w.remark FROM biz_work_record w JOIN biz_task_assignment a ON a.id=w.assignment_id AND a.company_id=w.company_id WHERE "+scope("w.")+" AND w.work_date BETWEEN ? AND ? ORDER BY w.company_id,w.id",f.company,f.company,f.from,f.to));List<Map<String,Object>> counts=new ArrayList<>();for(var e:tables.entrySet())counts.add(Map.of("dataset",e.getKey(),"recordCount",e.getValue().size()));return Map.of("rows",counts,"summary",Map.of("datasets",tables.size()),"tables",tables);}
 public Map<String,Object> exportData(String kind,Long c,LocalDate from,LocalDate to,String group){perm("export");if(!TITLES.containsKey(kind))throw new ServiceException("报表类型无效",400);if(!allowed().contains(kind))throw new AccessDeniedException("无该报表导出权限");return dataset(kind,filter(c,from,to,group));}
 public Object safe(Object value){if(value instanceof BigDecimal number)return number.toPlainString();if(value instanceof Map<?,?> map){Map<String,Object> copy=new LinkedHashMap<>();for(var entry:map.entrySet())copy.put(String.valueOf(entry.getKey()),safe(entry.getValue()));return copy;}if(value instanceof Collection<?> collection){List<Object> copy=new ArrayList<>();for(Object item:collection)copy.add(safe(item));return copy;}return value;}
 public List<Map<String,Object>> priceTasks(){perm("price");if(platform())return bounded("SELECT id,title,unit,unit_price,price_version,status FROM biz_task WHERE publisher_type='PLATFORM' ORDER BY id DESC");Long c=tenant(null);if(!users.hasRole(SecurityUtils.getUserId(),"company_admin")&&!users.hasRole(SecurityUtils.getUserId(),"company_business"))throw new AccessDeniedException("仅发布管理者可报价");return bounded("SELECT id,title,unit,unit_price,price_version,status FROM biz_task WHERE publisher_type='COMPANY' AND company_id=? ORDER BY id DESC",c);}
 public record Price(BigDecimal unitPrice,Integer version,String opinion){}
 @Transactional public void price(long id,Price in){perm("price");if(!platform()){Long c=tenant(null);db.queryForList("SELECT id FROM biz_company WHERE id=? AND status='ACTIVE' FOR UPDATE",c);}var task=tasks.task(id,true);tasks.owner(task);if(Set.of("COMPLETED","ARCHIVED").contains(task.get("status")))throw new ServiceException("已完成任务不可改报价",409);if(in.unitPrice()==null||in.unitPrice().signum()<0||in.unitPrice().scale()>4||in.unitPrice().compareTo(new BigDecimal("99999999999999.9999"))>0||in.version()==null||in.opinion()==null||in.opinion().isBlank()||in.opinion().length()>500)throw new ServiceException("单价、版本或报价说明无效",400);if(in.version().intValue()!=((Number)task.get("price_version")).intValue())throw new ServiceException("报价版本已变化",409);int version=in.version()+1;db.update("UPDATE biz_task SET unit_price=?,price_version=? WHERE id=?",in.unitPrice(),version,id);db.update("INSERT INTO biz_task_price_audit(task_id,company_id,old_price,new_price,price_version,opinion,actor_id) VALUES(?,?,?,?,?,?,?)",id,task.get("company_id"),task.get("unit_price"),in.unitPrice(),version,in.opinion(),SecurityUtils.getUserId()); }
 @Transactional public int snapshot(long pid,String opinion){perm("price");long user=SecurityUtils.getUserId();Long c=users.userCompany(user);if(c==null||!users.hasRole(user,"company_admin")&&!users.hasRole(user,"company_business"))throw new AccessDeniedException("仅本企业项目管理者可补录报价快照");if(opinion==null||opinion.isBlank()||opinion.length()>500)throw new ServiceException("补录原因必填",400);db.queryForList("SELECT id FROM biz_company WHERE id=? FOR UPDATE",c);var projects=db.queryForList("SELECT id,status FROM biz_project WHERE id=? AND company_id=? FOR UPDATE",pid,c);if(projects.isEmpty())throw new ServiceException("项目不存在或无权访问",404);if(!"ACTIVE".equals(projects.get(0).get("status")))throw new ServiceException("已完成或归档项目不允许补录",409);var links=db.queryForList("SELECT l.id,t.unit_price,t.price_version FROM biz_project_task l JOIN biz_task t ON t.id=l.task_id WHERE l.company_id=? AND l.project_id=? AND l.unit_price IS NULL AND t.unit_price IS NOT NULL FOR UPDATE",c,pid);for(var link:links){db.update("UPDATE biz_project_task SET unit_price=?,price_version=?,price_snapshot_time=CURRENT_TIMESTAMP WHERE id=? AND company_id=? AND unit_price IS NULL",link.get("unit_price"),link.get("price_version"),link.get("id"),c);db.update("INSERT INTO biz_execution_event(company_id,project_id,action,before_value,after_value,opinion,actor_id) VALUES(?,?,'PRICE_SNAPSHOT','未报价',?,?,?)",c,pid,String.valueOf(link.get("unit_price")),opinion,user);}return links.size();}
}
